package com.saleshub.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="sales") public class Sale { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User seller; @ManyToOne private Customer customer; @Enumerated(EnumType.STRING) private PaymentMethod paymentMethod; @Enumerated(EnumType.STRING) private SaleStatus status=SaleStatus.COMPLETED; private BigDecimal subtotal,discount,total; private Instant createdAt=Instant.now(); @OneToMany(cascade=CascadeType.ALL,orphanRemoval=true) private List<SaleItem> items=new ArrayList<>(); protected Sale(){} public Sale(User s,Customer c,PaymentMethod p,BigDecimal sub,BigDecimal dis){seller=s;customer=c;paymentMethod=p;subtotal=sub;discount=dis;total=sub.subtract(dis);} public Long getId(){return id;} public List<SaleItem> getItems(){return items;} public BigDecimal getTotal(){return total;} public SaleStatus getStatus(){return status;} public void addItem(SaleItem i){items.add(i);} public void cancel(){status=SaleStatus.CANCELLED;} }
